"""de — sira_c."""

T = {
"sira_151": ("Welcher Onkel des Propheten ﷺ nahm den Islam an und wurde einer seiner entschiedensten Verteidiger in Mekka?", ["Hamza ibn 'Abd al-Muttalib", "Abu Lahab", "Abu Talib", "Al-'Abbas"], "Hamza, Onkel und Milchbruder des Propheten ﷺ, nahm in Mekka den Islam an und wurde «der Löwe Allahs» genannt."),
"sira_152": ("In wessen Haus trafen sich die ersten Muslime in Mekka heimlich?", ["Im Haus von al-Arqam", "Im Haus von Abu Bakr", "Im Haus von Khadija", "Im Haus von Abu Talib"], "Das Haus von al-Arqam ibn Abi al-Arqam am Hügel Safa war der erste Versammlungs- und Lehrort."),
"sira_153": ("Welcher Gefährte, in Mekka bekehrt, wurde später als erster Lehrer nach Yathrib gesandt?", ["Mus'ab ibn 'Umayr", "Bilal ibn Rabah", "Khalid ibn al-Walid", "Abu Hurayra"], "Mus'ab ibn 'Umayr, ein junger Mekkaner aus edler Familie, wurde nach dem Bund von 'Aqaba nach Yathrib gesandt, um den Koran zu lehren."),
"sira_154": ("Mit welchem Befehl beginnt die Sure Al-Muddaththir, die den öffentlichen Ruf einleitete?", ["«O du Zugedeckter! Steh auf und warne»", "«Lies, im Namen deines Herrn»", "«Bekämpfe die Ungläubigen»", "«Wandere nach Medina aus»"], "«O du Zugedeckter! Steh auf und warne»."),
"sira_155": ("Welcher Vers befahl dem Propheten ﷺ, offen zu verkünden, was ihm geboten war?", ["«So verkünde denn offen, was dir befohlen wird»", "«Sei geduldig»", "«Rezitiere heimlich»", "«Zieh dich zurück»"], "«So verkünde denn offen, was dir befohlen wird, und wende dich von den Götzendienern ab»."),
"sira_156": ("Wo hängte Quraisch das Dokument des Boykotts gegen die Banu Haschim auf?", ["Im Inneren der Kaaba", "Am Stadttor", "Auf dem Markt von 'Ukaz", "Auf dem Hügel Safa"], "Der Text des Boykotts wurde in der Kaaba aufgehängt, bis der Pakt gebrochen und das Dokument aufgegeben wurde."),
"sira_157": ("In wessen Garten in Ta'if fand der Prophet ﷺ Zuflucht und erhielt eine Traube, nachdem er vertrieben worden war?", ["Im Garten von 'Utba und Schayba, wo ihn der Sklave 'Addas bediente", "Im Haus des Oberhaupts von Ta'if", "In einer durchziehenden Karawane", "Bei einem Schmied"], "Verwundet und aus Ta'if vertrieben, suchte er Zuflucht in einem Garten, wo ihm Trauben gereicht wurden, gebracht von einem christlichen Sklaven namens 'Addas."),
"sira_158": ("Welcher Gefährte, zunächst erbitterter Gegner, nahm den Islam an und wurde «der, der Wahrheit von Falschheit scheidet» genannt?", ["'Umar ibn al-Khattab", "Abu Sufyan", "Khalid ibn al-Walid", "'Amr ibn al-'As"], "'Umar ibn al-Khattab, anfangs feindselig, bekehrte sich in Mekka und erhielt den Titel al-Faruq."),
"sira_159": ("Bei welcher Familie stieg der Prophet ﷺ bei seiner Ankunft in Medina ab, dort wo seine Kamelstute niederkniete?", ["Bei Abu Ayyub al-Ansari", "Bei Sa'd ibn Mu'adh", "Bei Ubayy ibn Ka'b", "Bei Anas ibn Malik"], "Die Kamelstute kniete beim Haus von Abu Ayyub al-Ansari nieder, der den Propheten ﷺ bei seiner Ankunft beherbergte."),
"sira_160": ("Wie heißt der Friedhof von Medina, auf dem viele Gefährten bestattet sind?", ["Al-Baqi'", "Al-Mu'alla", "Al-Hijr", "Al-Quba"], "Baqi' al-Gharqad neben der Moschee des Propheten ﷺ ist der Friedhof von Medina."),
"sira_161": ("Von welcher Moschee sagt der Koran, sie sei «vom ersten Tag an auf Gottesfurcht gegründet»?", ["Die Moschee von Quba", "Die Heilige Moschee", "Die Al-Aqsa-Moschee", "Die Moschee von Kufa"], "«Eine Moschee, die vom ersten Tag an auf Gottesfurcht gegründet wurde, ist würdiger, dass du in ihr stehst»."),
"sira_162": ("In welcher Moschee betete der Prophet ﷺ, als der Befehl zur Änderung der Gebetsrichtung offenbart wurde?", ["Die Moschee der zwei Qiblas (Masjid al-Qiblatayn)", "Die Moschee von Quba", "Die Heilige Moschee", "Die Al-Aqsa-Moschee"], "Der Befehl kam während des Gebets; die Betenden wandten sich zur Kaaba, daher der Name «Moschee der zwei Qiblas»."),
"sira_163": ("Welche Pflicht wurde den Muslimen im zweiten Jahr der Hidschra vorgeschrieben?", ["Das Fasten des Monats Ramadan", "Die Pilgerfahrt", "Das Nachtgebet", "Die Reise nach Ta'if"], "Das Fasten des Ramadan wurde in Medina im zweiten Jahr nach der Hidschra zur Pflicht."),
"sira_164": ("Welcher Gefährte sah die Worte des Gebetsrufs im Traum, die der Prophet ﷺ dann übernahm?", ["'Abdullah ibn Zayd", "Bilal ibn Rabah", "Abu Bakr", "Mu'adh ibn Jabal"], "'Abdullah ibn Zayd berichtete den Traum vom Adhan; der Prophet ﷺ billigte ihn und beauftragte Bilal, ihn zu rufen."),
"sira_165": ("Was sagt der Koran über die Handvoll Erde, die der Prophet ﷺ bei Badr warf?", ["«Nicht du hast geworfen, als du warfst, sondern Allah hat geworfen»", "«Du hast gut gezielt»", "«Der Wind trug sie»", "«Die Engel warfen sie»"], "«Und nicht du hast geworfen, als du warfst, sondern Allah hat geworfen»."),
"sira_166": ("Wie beschreibt der Koran den Zustand einiger Gläubiger beim Aufbruch nach Badr?", ["Sie stritten darüber, als würden sie zum Tode getrieben", "Alle waren voller Eifer", "Sie weigerten sich aufzubrechen", "Sie baten um Aufschub"], "«Sie stritten mit dir über die Wahrheit, nachdem sie klar geworden war, als würden sie zum Tode getrieben»."),
"sira_167": ("Woran erinnert der Koran die Gläubigen bezüglich ihrer Lage vor dem Sieg?", ["Sie waren wenige und unterdrückt im Land, dann gab Allah ihnen Zuflucht und Hilfe", "Sie waren reich", "Sie waren zahlreich", "Sie herrschten bereits"], "«Und gedenkt, als ihr wenige wart und im Land unterdrückt… da gab Er euch Zuflucht und stärkte euch mit Seiner Hilfe»."),
"sira_168": ("Welcher Gefährte schlug bei Badr vor, das Heer zum Brunnen näher am Feind zu verlegen?", ["Al-Hubab ibn al-Mundhir", "Sa'd ibn Mu'adh", "Al-Miqdad", "Az-Zubayr"], "Al-Hubab ibn al-Mundhir fragte, ob die Stellung Offenbarung oder Meinung sei; als er erfuhr, dass es Meinung war, schlug er den Vormarsch zum Brunnen vor, und der Prophet ﷺ stimmte zu."),
"sira_169": ("Wie hieß die Wasserstelle, bei der die Schlacht von Badr stattfand?", ["Badr, ein Brunnen an der Karawanenstraße", "Zamzam", "Quba", "Al-Hudaybiyya"], "Badr war eine Wasserstelle an der Karawanenstraße zwischen Mekka und Syrien; die Schlacht erhielt davon ihren Namen."),
"sira_170": ("Welche Angelegenheit bezüglich der Gefangenen wurde nach Badr durch Offenbarung behandelt?", ["Das für die Gefangenen angenommene Lösegeld", "Die Verteilung des Wassers", "Die Wahl des Lagers", "Das Datum der Rückkehr"], "Die Stelle spricht von den Gefangenen und dem Lösegeld und erlaubt dann das Genommene als erlaubt und gut."),
"sira_171": ("Was wendete laut Sure Al 'Imran bei Uhud die Lage nach einem ersten Erfolg?", ["Der Ungehorsam und der Streit über den erhaltenen Befehl", "Die Zahl des Feindes", "Die Hitze", "Der Wassermangel"], "«…bis ihr den Mut verlort, über den Befehl strittet und ungehorsam wart»."),
"sira_172": ("Was sagt der Koran über jene, die auf dem Weg Allahs getötet werden?", ["Haltet sie nicht für tot: sie sind lebendig bei ihrem Herrn", "Sie schlafen bis zum Jüngsten Tag", "Sie kehren zurück", "Sie werden vergessen"], "«Und meine ja nicht, dass diejenigen, die auf Allahs Weg getötet worden sind, tot seien. Nein! Vielmehr sind sie lebendig bei ihrem Herrn und werden versorgt»."),
"sira_173": ("Auf welchem Hügel postierte der Prophet ﷺ bei Uhud die Bogenschützen?", ["Der Berg der Bogenschützen (Jabal ar-Rumat)", "Der Berg Safa", "Der Berg Thawr", "Der Berg Hira"], "Fünfzig Bogenschützen wurden auf einem Hügel postiert, der später «der Berg der Bogenschützen» hieß, mit dem Befehl, ihn nicht zu verlassen."),
"sira_174": ("Wie beschreibt die Sure Al-Ahzab die Prüfung der Belagerung Medinas?", ["Die Blicke wandten sich ab und die Herzen erreichten die Kehlen", "Die Stadt fiel", "Nur die Vorräte gingen aus", "Der Himmel verdunkelte sich"], "«Als sie von oben zu euch kamen und von unten, und als die Blicke sich abwandten und die Herzen die Kehlen erreichten»."),
"sira_175": ("Wie beschreibt der Koran den Ausgang der Grabenschlacht?", ["Allah trieb die Verbündeten voller Grimm zurück, ohne dass sie Gutes erlangten", "Eine lange Feldschlacht", "Ein Friedensvertrag", "Ein Rückzug der Muslime"], "«Und Allah wies diejenigen, die ungläubig waren, in ihrem Grimm zurück: sie erlangten nichts Gutes, und Allah genügte den Gläubigen im Kampf»."),
"sira_176": ("Wo liegt Hudaybiyya, der Ort des berühmten Vertrags?", ["Am Rand des heiligen Bezirks, westlich von Mekka", "Nahe Medina", "Im Jemen", "In Syrien"], "Hudaybiyya ist ein Ort am Rand des heiligen Bezirks von Mekka, wo der Vertrag geschlossen wurde."),
"sira_177": ("Welche Vision des Propheten ﷺ bestätigt der Koran nach Hudaybiyya?", ["Dass sie sicher in die Heilige Moschee eintreten würden, mit geschorenem oder gekürztem Haar", "Dass sie bei Khaybar siegen würden", "Dass sie eine Stadt bauen würden", "Dass sie nach Syrien reisen würden"], "«Allah hat Seinem Gesandten das Traumgesicht wahrhaftig gezeigt: Ihr werdet ganz gewiss in Sicherheit in die Heilige Moschee eintreten»."),
"sira_178": ("Woran erinnert die Sure Al-Fath bezüglich der in Mekka zurückgehaltenen Hände?", ["Allah hielt ihre Hände von euch und eure Hände von ihnen im Tal von Mekka zurück", "Er befahl zu kämpfen", "Er schloss die Wege", "Er sandte einen Sturm"], "«Und Er ist es, der im Tal von Mekka ihre Hände von euch und eure Hände von ihnen zurückhielt, nachdem Er euch den Sieg über sie gegeben hatte»."),
"sira_179": ("In welchem Jahr der Hidschra fand der Feldzug nach Khaybar statt?", ["Im siebten", "Im zweiten", "Im fünften", "Im zehnten"], "Khaybar fand im Jahr 7 der Hidschra statt, dem Jahr nach dem Vertrag von Hudaybiyya."),
"sira_180": ("Wie heißt die 'Umra, die im Jahr nach Hudaybiyya gemäß den Vertragsbedingungen vollzogen wurde?", ["'Umrat al-Qada", "Hajjat al-Wada'", "'Umrat al-Ji'rana", "Al-Hajj al-Akbar"], "Der Vertrag sah vor, dass die Muslime im folgenden Jahr wiederkämen; diese 'Umra heißt 'umrat al-qada."),
"sira_181": ("Welcher Herrscher zerriss den Brief des Propheten ﷺ, als er ihn erhielt?", ["Der König von Persien (Chosrau)", "Der Negus von Abessinien", "Der Statthalter von Bahrain", "Der König des Jemen"], "Der Prophet ﷺ sandte Briefe an die benachbarten Herrscher; der an den König von Persien wurde zerrissen."),
"sira_182": ("Welcher Gefährte überbrachte den Brief des Propheten ﷺ dem Negus von Abessinien und anderen Herrschern?", ["'Amr ibn Umayya ad-Damri", "Abu Hurayra", "Anas ibn Malik", "Ubayy ibn Ka'b"], "Boten wurden unter den Gefährten ausgewählt; 'Amr ibn Umayya ad-Damri wurde zum Negus gesandt."),
"sira_183": ("In welcher Richtung liegt Khaybar von Medina aus?", ["Im Norden", "Im Süden", "Im Osten", "Im Westen, am Meer"], "Khaybar ist eine befestigte Oase nördlich von Medina, an der Straße nach Syrien."),
"sira_184": ("Was wurde das Haus des Abu Sufyan am Tag der Eroberung Mekkas?", ["Ein sicherer Ort für jeden, der es betrat", "Ein Gefängnis", "Ein Lagerhaus", "Eine Moschee"], "Der Prophet ﷺ erklärte jeden für sicher, der die Heilige Moschee betrat, in seinem Haus blieb oder das Haus des Abu Sufyan betrat."),
"sira_185": ("Welches Jahr heißt «das Jahr der Eroberung» ('am al-fath)?", ["Das Jahr 8 der Hidschra", "Das Jahr 6 der Hidschra", "Das Jahr 10 der Hidschra", "Das Jahr 2 der Hidschra"], "Mekka wurde im Jahr 8 der Hidschra erobert, dem als «Jahr der Eroberung» bekannten Jahr."),
"sira_186": ("Welche Schlacht folgte kurz nach der Eroberung Mekkas, gegen die Stämme der Hawazin?", ["Hunayn", "Badr", "Uhud", "Khaybar"], "Hunayn fand kurz nach der Eroberung statt, in einem Tal zwischen Mekka und Ta'if."),
"sira_187": ("Was sandte Allah auf Seinen Gesandten ﷺ und die Gläubigen herab nach ihrer Bestürzung bei Hunayn?", ["Seine Ruhe (Sakina) und Heerscharen, die sie nicht sahen", "Regen", "Einen Wind", "Eine Verstärkung von Reitern"], "«Dann sandte Allah Seine Ruhe auf Seinen Gesandten und auf die Gläubigen herab und sandte Heerscharen herab, die ihr nicht saht»."),
"sira_188": ("Gegen welche Stadt zog das muslimische Heer nach Hunayn?", ["Ta'if", "Khaybar", "Tabuk", "Sanaa"], "Nach Hunayn belagerten die Muslime Ta'if, dessen Bewohner sich verschanzt hatten."),
"sira_189": ("Welchen Feldzug nennt der Koran «die Stunde der Bedrängnis» (sa'at al-'usra)?", ["Tabuk", "Badr", "Khaybar", "Hunayn"], "«Allah hat die Reue des Propheten, der Auswanderer und der Helfer angenommen, die ihm in der Stunde der Bedrängnis folgten»."),
"sira_190": ("Was sagt der Koran über die drei Gefährten, die bei Tabuk zurückblieben, vor ihrer Vergebung?", ["Die Erde wurde ihnen eng trotz ihrer Weite, dann nahm Allah ihre Reue an", "Sie wurden verbannt", "Sie zogen in den Jemen", "Sie wurden vergessen"], "«Und den Dreien, die zurückgelassen wurden: bis die Erde ihnen eng wurde trotz ihrer Weite… dann wandte Er Sich ihnen zu»."),
"sira_191": ("In welcher Richtung liegt Tabuk, das Ziel des letzten großen Feldzugs?", ["Im Norden, zur syrischen Grenze hin", "Im Süden, zum Jemen hin", "Im Osten, zum Irak hin", "Im Westen, am Roten Meer"], "Tabuk liegt nördlich von Medina an der Straße nach Syrien; es war der letzte große Feldzug des Propheten ﷺ."),
"sira_192": ("Welcher Gefährte rüstete einen großen Teil des Heeres von Tabuk aus eigenem Vermögen aus?", ["'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas", "Talha ibn 'Ubaydillah", "Abu Dharr"], "'Uthman ibn 'Affan stellte einen beträchtlichen Teil der Ausrüstung des «Heeres der Bedrängnis» (jaysh al-'usra)."),
"sira_193": ("Welcher Gefährte war der Erste, der einen Pfeil auf dem Weg Allahs abschoss?", ["Sa'd ibn Abi Waqqas", "Az-Zubayr ibn al-'Awwam", "Talha ibn 'Ubaydillah", "Abu 'Ubayda"], "Sa'd ibn Abi Waqqas, einer der allerersten Muslime, gilt als der Erste, der einen Pfeil auf dem Weg Allahs abschoss."),
"sira_194": ("Welcher Gefährte wird «der Jünger (hawari) des Gesandten Allahs ﷺ» genannt?", ["Az-Zubayr ibn al-'Awwam", "Abu Hurayra", "Salman al-Farisi", "Bilal"], "Az-Zubayr ibn al-'Awwam, ein Vetter des Propheten ﷺ, wurde sein Hawari genannt, sein enger Beistand."),
"sira_195": ("Welchem Gefährten wurde das Wissen um die Heuchler anvertraut, weshalb er «der Hüter des Geheimnisses» genannt wird?", ["Hudhayfa ibn al-Yaman", "Abu Musa al-Ash'ari", "'Ammar ibn Yasir", "Abu ad-Darda"], "Hudhayfa ibn al-Yaman ist als «sahib as-sirr» bekannt, jener, dem der Prophet ﷺ anvertraute, was er über die Heuchler wusste."),
"sira_196": ("Aus welchem Land stammte Salman, genannt «al-Farisi», der den Graben vorschlug?", ["Aus Persien", "Aus dem Jemen", "Aus Abessinien", "Aus Byzanz"], "Salman, persischer Herkunft, suchte lange nach der Wahrheit, bevor er sich dem Propheten ﷺ in Medina anschloss."),
"sira_197": ("Welche Frau, die Mutter von Anas ibn Malik, bot dem Propheten ﷺ den Dienst ihres Sohnes an?", ["Umm Sulaym", "Umm Salama", "Umm Ayman", "Umm Habiba"], "Umm Sulaym von den Ansar stellte ihren Sohn Anas dem Propheten ﷺ zum Dienst vor, als er nach Medina kam."),
"sira_198": ("Welche Gattin des Propheten ﷺ war für ihre große Gelehrsamkeit bekannt und überlieferte zahlreiche Hadithe?", ["'Aisha", "Sawda", "Juwayriya", "Maymuna"], "'Aisha, die Tochter Abu Bakrs, ist eine der größten Überliefererinnen von Hadithen und eine Autorität im religiösen Wissen."),
"sira_199": ("Welche Gattin des Propheten ﷺ war seine Cousine, und ihre Heirat wird in der Sure Al-Ahzab erwähnt?", ["Zaynab bint Jahsch", "Hafsa", "Umm Salama", "Safiyya"], "Die Heirat mit Zaynab bint Jahsch wird in der Sure Al-Ahzab (33:37) erwähnt."),
"sira_200": ("Welche Gattin des Propheten ﷺ riet zu dem Schritt, der die Krise von Hudaybiyya löste?", ["Umm Salama", "'Aisha", "Hafsa", "Zaynab bint Jahsch"], "Umm Salama riet dem Propheten ﷺ, hinauszugehen und selbst das Opfer und die Haarschur zu vollziehen: die Gefährten folgten sogleich."),
"sira_201": ("Wie lautet der vollständige Name des Propheten ﷺ, bis zu seinem Großvater?", ["Muhammad ibn 'Abdillah ibn 'Abd al-Muttalib", "Muhammad ibn Abi Talib", "Muhammad ibn al-'Abbas", "Muhammad ibn Haschim"], "Er ist Muhammad, Sohn des 'Abdullah, Sohn des 'Abd al-Muttalib, vom Stamm der Quraisch."),
"sira_202": ("Welcher andere Name des Propheten ﷺ, im Koran von 'Isa genannt, bedeutet «der Hochgelobte»?", ["Ahmad", "Al-Mustafa", "Al-Amin", "Abu-l-Qasim"], "'Isa verkündete einen Gesandten nach ihm, «dessen Name Ahmad ist» (Koran 61:6)."),
"sira_203": ("Wie lange dauerte die Offenbarung des Korans an den Propheten ﷺ?", ["Etwa dreiundzwanzig Jahre", "Zehn Jahre", "Vierzig Jahre", "Eine einzige Nacht"], "Die Offenbarung erstreckte sich über etwa dreiundzwanzig Jahre: dreizehn in Mekka und zehn in Medina."),
"sira_204": ("Welcher Gefährte war der erste freie erwachsene Mann, der den Islam annahm?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Uthman ibn 'Affan", "Sa'd ibn Abi Waqqas"], "Unter den freien erwachsenen Männern war Abu Bakr der Erste, der dem Ruf des Propheten ﷺ folgte."),
"sira_205": ("Welches Kind nahm als Erstes den Islam an?", ["'Ali ibn Abi Talib", "Anas ibn Malik", "Usama ibn Zayd", "'Abdullah ibn 'Umar"], "'Ali ibn Abi Talib, im Haus des Propheten ﷺ aufgewachsen, war das erste Kind, das glaubte."),
"sira_206": ("Welcher Freigelassene des Propheten ﷺ war der Erste unter den Freigelassenen, der den Islam annahm?", ["Zayd ibn Haritha", "Bilal ibn Rabah", "Suhayb ar-Rumi", "Salman al-Farisi"], "Zayd ibn Haritha, vom Propheten ﷺ freigelassen und wie ein Sohn aufgezogen, war der Erste unter den Freigelassenen, der glaubte."),
"sira_207": ("Welcher Vers beendete die rechtliche Adoption, indem er sagt, der Prophet ﷺ sei nicht der Vater eines ihrer Männer?", ["«Muhammad ist nicht der Vater irgendeines eurer Männer, sondern der Gesandte Allahs und das Siegel der Propheten»", "«Nennt sie nach ihren Vätern»", "«Blutsbande gehen vor»", "«Adoptiert nicht»"], "«Muhammad ist nicht der Vater irgendeines eurer Männer, sondern der Gesandte Allahs und das Siegel der Propheten»."),
"sira_208": ("An welchem Wochentag versammeln sich die Muslime zum in Medina eingeführten Gemeinschaftsgebet?", ["Am Freitag", "Am Samstag", "Am Sonntag", "Am Montag"], "Das Freitagsgebet (al-Jumu'a) wurde in Medina eingeführt und versammelt die Gemeinschaft jede Woche."),
"sira_209": ("Welcher Gefährte leitete auf seinen Befehl hin das Gebet während der letzten Krankheit des Propheten ﷺ?", ["Abu Bakr as-Siddiq", "'Umar ibn al-Khattab", "'Ali ibn Abi Talib", "Bilal"], "Der Prophet ﷺ befahl, dass Abu Bakr während seiner Krankheit das Gebet leiten solle; die Gefährten sahen darin ein Zeichen."),
"sira_210": ("Welcher Kalif wurde tödlich verwundet, während er das Morgengebet leitete?", ["'Umar ibn al-Khattab", "Abu Bakr", "'Ali ibn Abi Talib", "Mu'awiya"], "'Umar ibn al-Khattab wurde während des Fajr-Gebets in Medina niedergestochen und starb an seinen Wunden."),
"sira_211": ("Wie lange dauerte das Kalifat von Abu Bakr?", ["Etwa zwei Jahre", "Zehn Jahre", "Zwanzig Jahre", "Dreißig Jahre"], "Abu Bakr regierte etwa zwei Jahre bis zu seinem Tod, und 'Umar folgte ihm nach."),
"sira_212": ("Gegen welche Bewegung musste Abu Bakr zu Beginn seines Kalifats vorgehen?", ["Die Verweigerung der Zakat und den Abfall einiger Stämme", "Eine Invasion aus Persien", "Eine Hungersnot", "Einen Aufstand in Medina"], "Das erste Kalifat begann mit den sogenannten Ridda-Kriegen gegen Stämme, die die Zakat verweigerten oder den Islam verließen."),
"sira_213": ("Welchen Titel nahm 'Umar ibn al-Khattab als Oberhaupt der Gemeinschaft an?", ["Amir al-Mu'minin (Befehlshaber der Gläubigen)", "Sultan", "Malik", "Imam al-Haramayn"], "Der Titel amir al-mu'minin setzte sich unter 'Umar durch und wurde von den späteren Kalifen getragen."),
"sira_214": ("Welche Moschee in Jerusalem war die erste Gebetsrichtung der Muslime?", ["Die Al-Aqsa-Moschee", "Die Moschee von Quba", "Die Moschee des Propheten ﷺ", "Die Heilige Moschee"], "Die Muslime beteten zuerst in Richtung Jerusalem, bevor die Qibla zur Kaaba festgelegt wurde."),
"sira_215": ("Welches sind die drei Moscheen, zu denen die Reise besonders empfohlen ist?", ["Die Heilige Moschee, die Moschee des Propheten ﷺ und Al-Aqsa", "Quba, Al-Aqsa und Kufa", "Die Heilige Moschee, Quba und Damaskus", "Al-Aqsa, Kufa und Basra"], "Die Reise ist besonders zu drei Moscheen empfohlen: der Heiligen Moschee, der Moschee des Propheten ﷺ und der Al-Aqsa-Moschee."),
"sira_216": ("Wo hielt der Prophet ﷺ seine Abschiedspredigt am Tag von 'Arafa?", ["Im Tal von 'Urana, am Berg 'Arafat", "In Mina", "Vor der Kaaba", "In Muzdalifa"], "Die Abschiedspredigt wurde am Tag von 'Arafa im Tal von 'Urana am Fuß des Berges 'Arafat gehalten."),
"sira_217": ("Was erklärte der Prophet ﷺ in seiner Abschiedspredigt für unverletzlich?", ["Das Blut, das Gut und die Ehre eines jeden", "Die Handelswege", "Die Brunnen Medinas", "Die Palmenhaine"], "Er erklärte Blut, Gut und Ehre der Muslime für heilig, so heilig wie jener Tag, jener Monat und jene Stadt."),
"sira_218": ("Was hinterließ der Prophet ﷺ seiner Gemeinschaft laut seiner Abschiedspredigt, damit sie nicht irregehe?", ["Das Buch Allahs", "Einen Schatz", "Ein Heer", "Eine Karte"], "Er erinnerte sie daran, dass er unter ihnen zurückließ, woran sie festhalten sollten, um nicht irrezugehen: das Buch Allahs."),
"sira_219": ("In welchem Monat des muslimischen Kalenders findet die Pilgerfahrt statt, die der Prophet ﷺ zum Abschied vollzog?", ["Dhul-Hijja", "Ramadan", "Muharram", "Rajab"], "Die Abschiedspilgerfahrt fand im Dhul-Hijja des Jahres 10 der Hidschra statt."),
"sira_220": ("Wer wusch und hüllte den Leichnam des Propheten ﷺ nach seinem Tod ein?", ["Die Angehörigen seines Hauses, darunter 'Ali und al-'Abbas", "Nur die Ansar", "Bilal und Anas", "Die Leute von Quba"], "Seine eigene Familie besorgte dies, darunter 'Ali ibn Abi Talib und sein Onkel al-'Abbas."),
"sira_221": ("In welchem Monat des Hidschra-Jahres starb der Prophet ﷺ?", ["Rabi' al-Awwal", "Ramadan", "Schawwal", "Dhul-Qa'da"], "Der Prophet ﷺ starb in Medina im Monat Rabi' al-Awwal des Jahres 11 der Hidschra."),
"sira_222": ("Welchen Vers rezitierte Abu Bakr, um daran zu erinnern, dass der Prophet ﷺ sterblich war?", ["«Muhammad ist nur ein Gesandter; vor ihm sind Gesandte dahingegangen»", "«Wir haben dich als Barmherzigkeit gesandt»", "«Du bist von großartiger Wesensart»", "«Wenn Allahs Hilfe kommt»"], "«Muhammad ist nur ein Gesandter; vor ihm sind Gesandte dahingegangen. Wenn er nun stürbe oder getötet würde, würdet ihr euch auf den Fersen umkehren?»"),
"sira_223": ("Welcher Gefährte ist vor allem für die Menge der von ihm auswendig gelernten Hadithe bekannt?", ["Abu Hurayra", "Anas ibn Malik", "Jabir ibn 'Abdillah", "Abu Sa'id al-Khudri"], "Abu Hurayra verbrachte die letzten Jahre des Lebens des Propheten ﷺ an seiner Seite und wurde der produktivste Überlieferer von Hadithen."),
"sira_224": ("Welcher Gefährte, ein Vetter des Propheten ﷺ, wurde die große Autorität der Koranauslegung?", ["'Abdullah ibn 'Abbas", "'Abdullah ibn 'Umar", "'Abdullah ibn Mas'ud", "'Abdullah ibn az-Zubayr"], "'Abdullah ibn 'Abbas, für den der Prophet ﷺ um das Verständnis des Buches bat, wurde «der Dolmetscher des Korans» genannt."),
"sira_225": ("Welchen Gefährten sandte der Prophet ﷺ als Statthalter und Richter in den Jemen, und der jung in Syrien starb?", ["Mu'adh ibn Jabal", "Abu 'Ubayda ibn al-Jarrah", "'Amr ibn al-'As", "Khalid ibn al-Walid"], "Mu'adh ibn Jabal, ein Gelehrter unter den Gefährten, wurde in den Jemen gesandt und starb später noch jung in Syrien."),
"sira_226": ("Welches Tal liegt zwischen den beiden Hügeln Safa und Marwa, die bei der Pilgerfahrt begangen werden?", ["Das Tal von Mekka, um die Kaaba herum", "Das Tal von 'Urana", "Das Tal von Mina", "Das Tal von Badr"], "Safa und Marwa sind zwei kleine Hügel im Tal von Mekka, heute in die Heilige Moschee einbezogen."),
"sira_227": ("Welche zwei großen arabischen Stämme Medinas führten vor der Ankunft des Propheten ﷺ Krieg gegeneinander?", ["Die Aws und die Khazraj", "Quraisch und Hawazin", "Thaqif und Kinana", "Tamim und Bakr"], "Die Aws und die Khazraj, lange Feinde, bildeten nach der Ankunft des Propheten ﷺ gemeinsam die Ansar."),
"sira_228": ("Welcher Vers erinnert die Ansar daran, dass sie Feinde waren und Allah ihre Herzen vereinte?", ["«Ihr wart Feinde, und Er brachte eure Herzen zusammen»", "«Ihr wart arm»", "«Ihr wart wenige»", "«Ihr wart verloren»"], "«Und gedenkt der Gunst Allahs an euch: als ihr Feinde wart und Er eure Herzen zusammenbrachte, und ihr durch Seine Gunst Brüder wurdet»."),
"sira_229": ("Wie lobt der Koran die Ansar für ihre Aufnahme der Auswanderer?", ["Sie ziehen andere sich selbst vor, auch wenn sie selbst bedürftig sind", "Sie verkauften ihnen Land", "Sie liehen ihnen Geld", "Sie brachten sie außerhalb der Stadt unter"], "«Und sie ziehen sie sich selbst vor, auch wenn sie selbst Mangel leiden. Wer vor seiner eigenen Habsucht bewahrt bleibt, das sind die Erfolgreichen»."),
"sira_230": ("Wie nennt man die Gesamtheit der Aussprüche, Handlungen und Billigungen des Propheten ﷺ?", ["Die Sunna", "Der Koran", "Die Sira", "Der Tafsir"], "Die Sunna ist, was der Prophet ﷺ sagte, tat oder billigte; die Sira ist der Bericht seines Lebens."),
"sira_231": ("Wie nennt man die Generation nach der der Gefährten?", ["Die Tabi'un (die Nachfolger)", "Die Ansar", "Die Muhajirun", "Die Qurra'"], "Die Tabi'un sind jene, die die Gefährten trafen, ohne den Propheten ﷺ gesehen zu haben."),
"sira_232": ("Wie heißt die Überliefererkette eines Hadith?", ["Der Isnad", "Der Matn", "Der Tafsir", "Der Tajwid"], "Der Isnad ist die Überliefererkette; der Matn ist der Text des Hadith selbst."),
"sira_233": ("Welche beiden Hadithsammlungen gelten als die strengsten und werden «die beiden Sahih» genannt?", ["Sahih al-Bukhari und Sahih Muslim", "Die Sunan von Abu Dawud und at-Tirmidhi", "Der Muwatta' und der Musnad", "Die Sunan von an-Nasa'i und Ibn Maja"], "Sahih al-Bukhari und Sahih Muslim werden zusammen «die beiden Sahih» (as-sahihan) genannt."),
"sira_234": ("In welcher Stadt befinden sich die Moschee des Propheten ﷺ und sein Grab?", ["Medina", "Mekka", "Jerusalem", "Ta'if"], "Die Moschee des Propheten ﷺ und sein Grab befinden sich in Medina, der Stadt der Hidschra."),
"sira_235": ("Welchen Beinamen trägt Medina, bezogen auf das ihr zugeschriebene Licht?", ["Al-Madina al-Munawwara (die erleuchtete Stadt)", "Umm al-Qura", "Dar as-Salam", "Al-Mada'in"], "Medina wird al-Munawwara genannt; Mekka wiederum wird al-Mukarrama genannt."),
"sira_236": ("Welchen Namen gibt der Koran Mekka, «der Mutter der Städte»?", ["Umm al-Qura", "Al-Madina", "Al-Balad al-Amin", "Bakka"], "«…damit du die Mutter der Städte (Umm al-Qura) und die rings um sie warnst»."),
"sira_237": ("Was war der Beruf von Khadija, der ersten Gattin des Propheten ﷺ?", ["Kauffrau", "Ärztin", "Dichterin", "Weberin"], "Khadija bint Khuwaylid war eine angesehene Kauffrau von Mekka, die ihre Karawane dem jungen Muhammad ﷺ anvertraute."),
"sira_238": ("Wie lange war der Prophet ﷺ allein mit Khadija verheiratet?", ["Bis zu ihrem Tod; zu ihren Lebzeiten heiratete er keine andere", "Zwei Jahre", "Fünf Jahre", "Er heiratete sogleich weitere"], "Der Prophet ﷺ heiratete zu Lebzeiten Khadijas keine andere Frau; die weiteren Ehen kamen nach ihrem Tod."),
"sira_239": ("Wie heißt der Onkel des Propheten ﷺ, der ihn schützte, ohne den Islam anzunehmen?", ["Abu Talib", "Hamza", "Al-'Abbas", "Abu Lahab"], "Abu Talib, der Vater 'Alis, schützte seinen Neffen bis zu seinem Tod gegen Quraisch."),
"sira_240": ("Welcher Onkel des Propheten ﷺ geriet bei Badr in Gefangenschaft, bevor er den Islam annahm?", ["Al-'Abbas ibn 'Abd al-Muttalib", "Abu Talib", "Hamza", "Az-Zubayr ibn 'Abd al-Muttalib"], "Al-'Abbas, Onkel des Propheten ﷺ und Stammvater der Abbasiden, wurde bei Badr gefangen genommen und nahm später den Islam an."),
"sira_241": ("Wie nennt man die Gefährten, die an der Schlacht von Badr teilnahmen?", ["Die Badriyyun (die Leute von Badr)", "Die Ansar", "Die Muhajirun", "Die Uhudiyyun"], "Die bei Badr anwesenden Gefährten sind als Badriyyun bekannt, und dieser Vorzug ist ihnen eigen."),
"sira_242": ("Welchen Anteil der Beute behält der Koran Allah, dem Gesandten, den Verwandten, den Waisen, den Armen und dem Reisenden vor?", ["Das Fünftel", "Die Hälfte", "Das Zehntel", "Das Drittel"], "«Wisst, dass von allem, was ihr erbeutet, ein Fünftel Allah gehört und dem Gesandten, den Verwandten, den Waisen, den Armen und dem Reisenden»."),
"sira_243": ("Welcher Vers, mit der Abschiedspredigt verbunden, begründet die Gleichheit der Völker vor Allah?", ["«Der Edelste von euch bei Allah ist der Gottesfürchtigste»", "«Die Menschen stammen von einem Vater»", "«Keiner trägt die Last eines anderen»", "«Kein Zwang in der Religion»"], "«O ihr Menschen, Wir haben euch von einem männlichen und einem weiblichen Wesen erschaffen… der Edelste von euch bei Allah ist der Gottesfürchtigste»."),
"sira_244": ("Wie viele nahmen am zweiten Bund von 'Aqaba teil, der entscheidenden Begegnung mit den Leuten von Yathrib?", ["Eine Abordnung von mehr als siebzig Personen", "Drei", "Zehn", "Fünfhundert"], "Der zweite Bund von 'Aqaba versammelte eine Abordnung von mehr als siebzig Männern und Frauen aus Yathrib."),
"sira_245": ("Wie viele Naqibs (Verantwortliche) ließ der Prophet ﷺ beim Bund von 'Aqaba unter den Leuten von Yathrib bestimmen?", ["Zwölf", "Vier", "Sieben", "Zwanzig"], "Zwölf Naqibs wurden gewählt, um die Gruppen der Abordnung von Yathrib zu vertreten und für ihren Bund einzustehen."),
"sira_246": ("Welchen Namen nahm Medina nach der Hidschra an?", ["Madinat an-Nabi, die Stadt des Propheten ﷺ", "Yathrib", "Nur Tayba", "Al-Qura"], "Yathrib wurde Madinat an-Nabi genannt, «die Stadt des Propheten ﷺ», abgekürzt zu al-Madina."),
"sira_247": ("Welcher Kalif ließ den Koran in amtlichen Abschriften kopieren und in die Provinzen senden?", ["'Uthman ibn 'Affan", "Abu Bakr", "'Umar", "'Ali"], "Abu Bakr ließ den Text sammeln; 'Uthman ließ amtliche Abschriften anfertigen und in die großen Städte senden."),
"sira_248": ("In welcher Sprache wurde der Koran dem Propheten ﷺ offenbart?", ["Auf Arabisch", "Auf Aramäisch", "Auf Persisch", "Auf Griechisch"], "Der Koran wurde in klarer arabischer Sprache offenbart, der Sprache des eigenen Volkes des Propheten ﷺ."),
"sira_249": ("Welchen Gefährten sandte der Prophet ﷺ nach Bahrain, und er kehrte mit dessen Abgaben zurück?", ["Abu 'Ubayda ibn al-Jarrah", "Bilal", "Anas ibn Malik", "Abu Dharr"], "Abu 'Ubayda ibn al-Jarrah, genannt «der Vertrauenswürdige dieser Gemeinschaft», kehrte aus Bahrain mit dessen Abgaben zurück."),
"sira_250": ("Welches Ereignis markiert den Beginn des muslimischen Kalenders?", ["Die Hidschra von Mekka nach Medina", "Die Geburt des Propheten ﷺ", "Die erste Offenbarung", "Die Eroberung Mekkas"], "Der Hidschra-Kalender beginnt mit dem Jahr der Hidschra, eine Entscheidung, die im Kalifat 'Umars getroffen wurde."),
}
